"use client";

import { useMemo, useState, type CSSProperties, type ReactNode } from "react";
import { DataGrid, defineColumns } from "@/registry/default/components/data-grid/data-grid";
import { Button } from "@/components/ui/button";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 150, flex: 2 },
  { id: "active", header: "Active", accessorKey: "active", type: "checkbox", width: 80, flex: 1 },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 90, flex: 1 },
] as const);

const RADII = ["0", "0.625rem", "1rem"] as const;
const TINT = "oklch(0.55 0.2 300)";

/** The grid takes its corners from `--radius`, its accent from `--primary`, and its surfaces from the `.dark` tokens. */
export default function DataGridColorsRadiusDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(20), []);
  const [radius, setRadius] = useState<(typeof RADII)[number]>("0.625rem");
  const [tinted, setTinted] = useState(false);
  const [dark, setDark] = useState(false);
  const style = { "--radius": radius, ...(tinted ? { "--primary": TINT } : {}) } as CSSProperties;

  return (
    <div className="flex w-full flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2 text-sm">
        <span className="text-muted-foreground">--radius</span>
        {RADII.map((value) => (
          <Button key={value} size="sm" variant={radius === value ? "default" : "outline"} onClick={() => setRadius(value)}>
            {value}
          </Button>
        ))}
        <Button size="sm" variant={tinted ? "default" : "outline"} onClick={() => setTinted(!tinted)}>
          Tinted primary
        </Button>
        <Button size="sm" variant={dark ? "default" : "outline"} onClick={() => setDark(!dark)}>
          Dark
        </Button>
      </div>
      <div className={dark ? "dark rounded-md bg-background p-3 text-foreground" : "rounded-md bg-background p-3 text-foreground"} style={style}>
        <DataGrid className="h-[280px] w-full" defaultData={rows} columns={columns} getRowId={(row) => row.id} />
      </div>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
